import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseDuration } from './duration.mjs';

test('is exported', () => {
  assert.equal(typeof parseDuration, 'function');
});

test('parses valid durations', () => {
  const cases = {
    '1h30m': 5400,
    '90s': 90,
    '2h': 7200,
    '1h0m5s': 3605,
    '45m': 2700,
    '1h30m15s': 5415,
    '1h5s': 3605,
    '5m10s': 310,
    '0s': 0,
    '0h0m0s': 0,
    '00090s': 90,
    '100h': 360000,
  };
  for (const [input, expected] of Object.entries(cases)) {
    assert.equal(parseDuration(input), expected, input);
  }
});

test('ignores surrounding whitespace', () => {
  assert.equal(parseDuration('  1h30m  '), 5400);
  assert.equal(parseDuration('\t90s\n'), 90);
});

test('throws TypeError on invalid input', () => {
  const bad = [
    '',
    '   ',
    'h',
    '5',
    '1h30',
    '10x',
    '1d',
    '1.5h',
    '1h 30m',
    '1 h',
    '-5s',
    '-1h30m',
    '+5s',
    '1h-5m',
    '1h1h',
    '30s1m',
    '30m1h',
    '1s1h',
    '1H',
    '1h30m ?',
    'abc',
    '1e3s',
    '١s',
  ];
  for (const input of bad) {
    assert.throws(() => parseDuration(input), TypeError, JSON.stringify(input));
  }
});

test('throws TypeError on non-string input', () => {
  for (const input of [undefined, null, 90, {}, []]) {
    assert.throws(() => parseDuration(input), TypeError);
  }
});

